import { getPageType, getABTestFeatures, safeDocument, safeWindow, safePerformance, } from "./utils/index.js";
export const createEventSender = (sendData, pageLoadTime, config, shouldSend) => {
    const state = {
        pageStartTime: safePerformance.now(),
        activeStartTime: safeDocument.hidden ? null : safePerformance.now(),
        totalActiveTime: 0,
        isPageVisible: !safeDocument.hidden,
        hasExited: false,
    };
    function resetTime() {
        state.pageStartTime = safePerformance.now();
        state.activeStartTime = safeDocument.hidden
            ? null
            : state.pageStartTime;
        state.totalActiveTime = 0;
        state.isPageVisible = !safeDocument.hidden;
        state.hasExited = false;
    }
    function handleVisibilityChange() {
        const now = safePerformance.now();
        state.isPageVisible = !safeDocument.hidden;
        if (safeDocument.hidden) {
            if (state.activeStartTime !== null) {
                state.totalActiveTime += now - state.activeStartTime;
                state.activeStartTime = null;
            }
        }
        else {
            state.activeStartTime = now;
        }
    }
    function handlePageExit() {
        if (!config.exit)
            return;
        if (!shouldSend())
            return;
        // Both beforeunload and pagehide fire on a single navigation: guard so
        // exit is emitted once per page life (reset by resetTime on SPA nav).
        if (state.hasExited)
            return;
        state.hasExited = true;
        const now = safePerformance.now();
        const timeOnPage = now - state.pageStartTime;
        if (state.isPageVisible && state.activeStartTime !== null) {
            state.totalActiveTime += now - state.activeStartTime;
        }
        void sendData('exit', {
            timeOnPage: Math.round(timeOnPage),
            activeTime: Math.round(state.totalActiveTime),
        });
    }
    function sendClick(event) {
        if (!shouldSend())
            return;
        const target = event.target;
        if (!target)
            return;
        const mouseEvent = event;
        const xPos = typeof mouseEvent.pageX === 'number' ? mouseEvent.pageX : 0;
        const yPos = typeof mouseEvent.pageY === 'number' ? mouseEvent.pageY : 0;
        const clickData = {
            elementType: target.tagName.toLowerCase(),
            elementId: target.id || undefined,
            elementHref: target.href || undefined,
            xPos,
            yPos,
        };
        void sendData('click', clickData);
    }
    function sendFormSubmit(event) {
        if (!shouldSend())
            return;
        const form = event.target;
        if (!form)
            return;
        void sendData('form_submit');
    }
    const hasDocumentListeners = config.exit &&
        safeDocument.addEventListener('visibilitychange', handleVisibilityChange);
    const hasWindowListeners = config.exit &&
        safeWindow.addEventListener('beforeunload', handlePageExit) &&
        safeWindow.addEventListener('pagehide', handlePageExit);
    function handlePageShow(event) {
        try {
            const ps = event;
            if (ps.persisted && config.pageView && shouldSend()) {
                // Send a page_view event when restored from BFCache
                const location = safeWindow.location;
                const pageViewData = {
                    pageTitle: safeDocument.title,
                    pageType: getPageType(location.pathname),
                    path: location.pathname,
                    referrer: safeDocument.referrer,
                };
                void sendData('page_view', pageViewData, { features: getABTestFeatures() }, 'high');
                resetTime();
            }
        }
        catch { }
    }
    // listen for pageshow for BFCache restores
    let hasPageShowListener = false;
    try {
        hasPageShowListener = safeWindow.addEventListener('pageshow', handlePageShow);
    }
    catch { }
    resetTime();
    return {
        sendPageView: () => {
            if (!config.pageView)
                return;
            if (!shouldSend())
                return;
            if (state.pageStartTime && state.totalActiveTime > 0) {
                handlePageExit();
            }
            resetTime();
            const location = safeWindow.location;
            const pageViewData = {
                pageTitle: safeDocument.title,
                pageType: getPageType(location.pathname),
                path: location.pathname,
                referrer: safeDocument.referrer,
            };
            void sendData('page_view', pageViewData, {
                features: getABTestFeatures(),
            }, 'high');
        },
        initClickSending: () => {
            if (!config.click)
                return;
            safeDocument.addEventListener('click', sendClick);
        },
        initFormSending: () => {
            if (!config.form)
                return;
            safeDocument.addEventListener('submit', sendFormSubmit);
        },
        sendModalView: (modalId, modalType) => {
            if (!config.modal)
                return;
            if (!shouldSend())
                return;
            void sendData('modal_view', {
                modalId,
                modalType,
            });
        },
        destroy: () => {
            if (hasDocumentListeners) {
                safeDocument.removeEventListener('visibilitychange', handleVisibilityChange);
            }
            if (hasWindowListeners) {
                safeWindow.removeEventListener('beforeunload', handlePageExit);
                safeWindow.removeEventListener('pagehide', handlePageExit);
            }
            if (hasPageShowListener) {
                safeWindow.removeEventListener('pageshow', handlePageShow);
            }
            if (config.click) {
                safeDocument.removeEventListener('click', sendClick);
            }
            if (config.form) {
                safeDocument.removeEventListener('submit', sendFormSubmit);
            }
        },
    };
};
