import { defaultConfig } from "./defaultConfig.js";
export const createConfig = (userConfig) => ({
    ...defaultConfig,
    ...userConfig,
    events: {
        ...defaultConfig.events,
        ...userConfig.events,
    },
    urlSanitization: userConfig.urlSanitization
        ? {
            ...defaultConfig.urlSanitization,
            ...userConfig.urlSanitization,
        }
        : defaultConfig.urlSanitization,
});
