import { logWarn } from "./utils/index.js";
export function createPerformanceObserver(sendData, debug) {
    return {
        initializeObserver: () => {
            if (typeof window !== 'undefined' &&
                window.PerformanceObserver &&
                window.PerformanceNavigationTiming) {
                const observer = new PerformanceObserver((list) => {
                    list.getEntries().forEach((entry) => {
                        if (entry.entryType === 'navigation') {
                            const navEntry = entry;
                            const performanceData = {
                                pageLoadTime: Math.round(navEntry.loadEventEnd - navEntry.startTime),
                                dnsTime: Math.round(navEntry.domainLookupEnd -
                                    navEntry.domainLookupStart),
                                tcpTime: Math.round(navEntry.connectEnd - navEntry.connectStart),
                                ttfb: Math.round(navEntry.responseStart -
                                    navEntry.requestStart),
                            };
                            void sendData('performance', performanceData);
                        }
                    });
                });
                observer.observe({ entryTypes: ['navigation'] });
            }
            else {
                logWarn(debug, 'PerformanceObserver API is not supported');
            }
        },
    };
}
